                        seen.add((yy, xx))
                        stack.append((yy, xx))
            out.append((color, cells))
    return out


def _orientations(points):
    result = []
    for reflect in (1, -1):
        for rot in range(4):
            transformed = []
            for y, x in points:
                x *= reflect
                for _ in range(rot):
                    y, x = x, -y
                transformed.append((y, x))
            miny = min(y for y, x in transformed)
            minx = min(x for y, x in transformed)
            result.append(frozenset((y - miny, x - minx) for y, x in transformed))
    return result


def _contained(source, host):
    # Search for the whole source silhouette as a subset of the host silhouette.
    hy = [y for y, x in host]
    hx = [x for y, x in host]
    hset = set(host)
    for form in _orientations(source):
        maxy = max(y for y, x in form)
        maxx = max(x for y, x in form)
        for y0 in range(min(hy), max(hy) - maxy + 1):
            for x0 in range(min(hx), max(hx) - maxx + 1):
                if all((y + y0, x + x0) in hset for y, x in form):
                    return True
    return False


